import { config } from "../config";
import { err, ok, type ApiError, type Result } from "../lib/result";
import { TransportError, withRetry, type RetryOptions } from "./transport";

export interface RequestOptions {
  method?: "GET" | "POST" | "PUT" | "DELETE";
  /** JSON-encoded, except a Blob, which is sent as it is. */
  body?: unknown;
  retry?: Partial<RetryOptions>;
}

async function send(path: string, options: RequestOptions): Promise<unknown> {
  const raw = options.body instanceof Blob;
  const response = await fetch(`${config.apiBaseUrl}${path}`, {
    method: options.method ?? "GET",
    headers: raw ? {} : { "content-type": "application/json" },
    body: options.body === undefined ? undefined : raw ? (options.body as Blob) : JSON.stringify(options.body),
    signal: AbortSignal.timeout(config.requestTimeoutMs),
  });
  if (!response.ok) throw new TransportError(response.status, await response.text());
  return response.status === 204 ? undefined : response.json();
}

/** One Orders API call: retried in the transport, every failure returned as an ApiError. */
export async function request<T>(path: string, options: RequestOptions = {}): Promise<Result<T>> {
  try {
    return ok((await withRetry(() => send(path, options), options.retry)) as T);
  } catch (error) {
    const status = error instanceof TransportError ? error.status : 0;
    const apiError: ApiError = { status, code: status === 0 ? "network" : `http_${status}`, message: String(error) };
    return err(apiError);
  }
}

