import { logger } from "../lib/logger";

export interface RetryOptions {
  attempts: number;
  baseDelayMs: number;
}

const DEFAULT_RETRY: RetryOptions = { attempts: 3, baseDelayMs: 200 };

/** An HTTP answer that was not 2xx. */
export class TransportError extends Error {
  constructor(readonly status: number, message: string) {
    super(message);
    this.name = "TransportError";
  }
}

const sleep = (ms: number) => new Promise<void>(resolve => setTimeout(resolve, ms));

function retryable(error: unknown): boolean {
  return !(error instanceof TransportError) || error.status === 429 || error.status >= 500;
}

/** Runs `send` again after network errors, 429 and 5xx answers, with exponential backoff between attempts. */
export async function withRetry<T>(send: () => Promise<T>, options: Partial<RetryOptions> = {}): Promise<T> {
  const { attempts, baseDelayMs } = { ...DEFAULT_RETRY, ...options };
  let lastError: unknown;
  for (let attempt = 1; attempt <= attempts; attempt++) {
    try {
      return await send();
    } catch (error) {
      lastError = error;
      if (!retryable(error) || attempt === attempts) break;
      logger.warn("retrying request", { attempt, error: String(error) });
      await sleep(baseDelayMs * 2 ** (attempt - 1));
    }
  }
  throw lastError;
}

