/** A parameterised statement: text with $1, $2, ... placeholders and the values that fill them. */
export interface Sql {
  readonly text: string;
  readonly values: readonly unknown[];
}

/** Tagged template: each interpolated value becomes a numbered placeholder, so values never reach the statement text. */
export function q(strings: TemplateStringsArray, ...values: unknown[]): Sql {
  let text = strings[0] ?? "";
  for (let index = 1; index < strings.length; index++) text += `$${index}${strings[index]}`;
  return { text, values };
}

