import type { OrderLine } from "../api/orders";

export const VAT_RATE = 0.2;
export const FREE_SHIPPING_FROM_CENTS = 5_000;
export const SHIPPING_CENTS = 495;

export interface OrderTotals {
  subtotalCents: number;
  vatCents: number;
  shippingCents: number;
  totalCents: number;
}

export function subtotalCents(lines: readonly OrderLine[]): number {
  return lines.reduce((sum, line) => sum + line.quantity * line.unitPriceCents, 0);
}

export function orderTotals(lines: readonly OrderLine[]): OrderTotals {
  const subtotal = subtotalCents(lines);
  const vat = Math.round(subtotal * VAT_RATE);
  const shipping = subtotal >= FREE_SHIPPING_FROM_CENTS ? 0 : SHIPPING_CENTS;
  return { subtotalCents: subtotal, vatCents: vat, shippingCents: shipping, totalCents: subtotal + vat + shipping };
}

