import { z } from "zod";
import { updateUser } from "../api/users";

const UpdateUserBody = z.object({
  name: z.string().min(1).max(100).optional(),
  email: z.string().email().optional(),
});

export async function updateUserHandler(request: Request, userId: string): Promise<Response> {
  const parsed = UpdateUserBody.safeParse(await request.json());
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 400 });
  const result = await updateUser(userId, parsed.data);
  if (!result.ok) return Response.json({ error: result.error.message }, { status: result.error.status || 502 });
  return Response.json(result.value);
}

